(function(){ 'use strict'; if(window.__svCategoryAliasRepairStarted)return; window.__svCategoryAliasRepairStarted=true; window.__svCategoryAliasRepairDone=false; function normalize(value){ return String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim().toLowerCase().replace(/\s+/g,' '); } function validImage(value){ var url=String(value||'').trim(); return !!url && !/unsplash\.com|placeholder|logo-vivaliz|no[-_ ]?image|sem[-_ ]?imagem/i.test(url) && url.indexOf('/public/assets/category-images/')===-1 && (/^https?:\/\//i.test(url)||url.charAt(0)==='/'); } function rowImages(row){ var images=[]; [row&&row.image_url,row&&row.image].forEach(function(value){ if(validImage(value))images.push(String(value).trim()); }); var gallery=row&&Array.isArray(row.images)?row.images:[]; gallery.forEach(function(value){ var candidate=value&&typeof value==='object'?(value.url||value.image_url||value.src||''):value; if(validImage(candidate))images.push(String(candidate).trim()); }); return images.filter(function(value,index,all){return all.indexOf(value)===index;}); } var aliases={ 'rodizios & rodas':['rodizios','rodas para carrinhos e moveis'], 'ferramentas':['ferramentas','ferramentas manuais','caixas de ferramentas'], 'organizacao':['armarios e organizacao'], 'jardim & floreiras':['floreiras e jardim','vasos decorativos'], 'ferragens & fixacao':['fixacao e ferragem','ferragens e fixacao'] }; function fetchPage(page){ return fetch('/api/catalog/products.php?limit=200&page='+encodeURIComponent(String(page)),{ headers:{Accept:'application/json'},credentials:'same-origin' }).then(function(response){ if(!response.ok)throw new Error('category_alias_products_request_failed'); return response.json(); }).then(function(data){ return { rows:data&&Array.isArray(data.products)?data.products:[], totalPages:Math.max(1,Number(data&&data.total_pages)||1) }; }); } function fetchAll(){ var rows=[]; function load(page,totalPages){ return fetchPage(page).then(function(result){ rows=rows.concat(result.rows); var pages=Math.max(totalPages||1,result.totalPages||1); return page<pages?load(page+1,pages):rows; }); } return load(1,1); } function choose(label,rows,used){ var key=normalize(label); var accepted=aliases[key]||[key]; var candidates=rows.filter(function(row){ return accepted.indexOf(normalize(row&&row.category))!==-1; }).map(function(row){ return {row:row,images:rowImages(row)}; }).filter(function(item){return item.images.length>0;}); candidates.sort(function(a,b){ var aScore=(Number(a.row&&a.row.stock)>0?4:0)+(Number(a.row&&a.row.price)>0?2:0); var bScore=(Number(b.row&&b.row.stock)>0?4:0)+(Number(b.row&&b.row.price)>0?2:0); return bScore-aScore; }); for(var i=0;i<candidates.length;i+=1){ for(var j=0;j<candidates[i].images.length;j+=1){ var url=candidates[i].images[j]; if(!used[url])return {row:candidates[i].row,url:url}; } } return null; } function finish(){window.__svCategoryAliasRepairDone=true;} function repair(cards){ fetchAll().then(function(rows){ var used={}; cards.forEach(function(card){ var title=card.querySelector('strong'); var image=card.querySelector('img.category-slide-img'); if(!title||!(image instanceof HTMLImageElement))return; if(image.dataset.svCategorySource==='catalog'){ used[image.currentSrc||image.src]=true; return; } var label=String(title.textContent||'').trim(); var selected=choose(label,rows,used); if(!selected)return; var fallback=image.currentSrc||image.getAttribute('src')||''; image.onerror=function(){ image.onerror=null; image.src=fallback; image.dataset.svCategorySource='local-fallback'; delete image.dataset.svProductSku; }; image.src=selected.url; image.alt=String(selected.row.name||('Produto da categoria '+label)); image.dataset.svCategorySource='catalog'; image.dataset.svProductSku=String(selected.row.sku||selected.row.id||''); image.loading='lazy'; image.decoding='async'; used[selected.url]=true; card.classList.add('has-real-image'); }); }).then(finish,finish); } function waitForPrimary(){ var cards=Array.prototype.slice.call(document.querySelectorAll('.home-categories .category-slide')); if(!cards.length){finish();return;} var ready=cards.every(function(card){ var image=card.querySelector('img.category-slide-img'); return image instanceof HTMLImageElement&&!!image.dataset.svCategorySource; }); if(ready){repair(cards);return;} window.setTimeout(waitForPrimary,120); } if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',waitForPrimary,{once:true}); else waitForPrimary(); })();